import { Annotation } from "@langchain/langgraph";
import {
  ExecutionPlan,
  ArchitectureProfile,
  DesignSpecifications,
  TicketClassification,
} from "./schema";

export type {
  ExecutionPlan,
  ArchitectureProfile,
  DesignSpecifications,
  TicketClassification,
} from "./schema";

/**
 * Defines the structure of a generated file.
 */
export interface GeneratedFile {
  filePath: string;
  fileContent: string;
}

export interface Metrics {
  startTime: number;
  endTime?: number;
  totalDuration?: number;
  nodeExecutionTimes: Record<string, number>;
  nodeTokenUsage: Record<
    string,
    { prompt: number; completion: number; total: number }
  >;
  nodeCallCounts: Record<string, number>;
  totalFilesGenerated: number;
  totalFilesModified: number;
  validationRetries: number;
  totalRounds: number;
}

/**
 * The main state object for the LangGraph agent workflow.
 * This acts as the shared memory between agents.
 */
export const AgentState = Annotation.Root({
  /**
   * The ID of the Jira ticket (e.g., PROJ-123).
   */
  ticketId: Annotation<string>({
    reducer: (x, y) => {
      if (y === undefined || y === null) {
        return x;
      }
      return y;
    },
  }),

  /**
   * The title of the Jira ticket.
   */
  ticketSummary: Annotation<string>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The detailed description from the Jira ticket.
   */
  ticketDescription: Annotation<string>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * A text representation of the project's current file structure.
   */
  codebaseTree: Annotation<string>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The plan drafted by the Product Manager agent.
   */
  executionPlan: Annotation<ExecutionPlan>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The code generated by the Frontend Engineer agent.
   */
  generatedCode: Annotation<GeneratedFile[]>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The full list of files being created/modified in this sprint (text representation).
   * Used to give the Engineer context about sibling files.
   */
  fullExecutionPlan: Annotation<string>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * A map of file dependencies (file -> imported files).
   */
  dependencyMap: Annotation<Record<string, string[]>>({
    reducer: (x, y) => ({ ...x, ...y }),
  }),

  /**
   * The project configuration context (Next.js version, Tailwind, etc.).
   */
  projectContext: Annotation<string>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The structured Architecture Profile generated by the Architecture Agent.
   */
  architectureProfile: Annotation<ArchitectureProfile>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The structured Design Specifications generated by the Design Agent.
   */
  designSpecifications: Annotation<DesignSpecifications>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The classification of the ticket (complexity, type).
   */
  ticketClassification: Annotation<TicketClassification>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * Whether the generated code needs revision.
   */
  needsRevision: Annotation<boolean>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The validation errors found during the review.
   */
  validationErrors: Annotation<string[]>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The number of consecutive validation API crashes. Resets to 0 on a successful validation call.
   */
  validationCrashCount: Annotation<number>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The number of retries within the current round (0–3). Resets to 0 on each new round.
   */
  retryCount: Annotation<number>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * The total number of rounds completed (unlimited). Increments each time retries are exhausted.
   */
  roundCount: Annotation<number>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * Non-critical validation warnings (style/quality issues). Non-blocking after round 5.
   */
  validationWarnings: Annotation<string[]>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * History of validation errors from each past retry, used to prevent repeating mistakes.
   * Each element is the list of errors from one retry attempt.
   */
  errorAttemptHistory: Annotation<string[][]>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * Whether the validation node experienced a technical failure (crash/invalid output).
   */
  validationCrashed: Annotation<boolean>({
    reducer: (x, y) => y ?? x,
  }),

  /**
   * Performance and usage metrics.
   */
  metrics: Annotation<Metrics>({
    reducer: (current, update) => {
      // If update is null/undefined, keep current
      if (!update)
        return (
          current || {
            startTime: Date.now(),
            nodeExecutionTimes: {},
            nodeTokenUsage: {},
            nodeCallCounts: {},
            totalFilesGenerated: 0,
            totalFilesModified: 0,
            validationRetries: 0,
          }
        );

      // Merge nodeCallCounts by summing values
      const mergedCallCounts = { ...(current?.nodeCallCounts || {}) };
      if (update.nodeCallCounts) {
        Object.entries(update.nodeCallCounts).forEach(([node, count]) => {
          mergedCallCounts[node] = (mergedCallCounts[node] || 0) + count;
        });
      }

      return {
        ...current,
        ...update,
        nodeExecutionTimes: {
          ...(current?.nodeExecutionTimes || {}),
          ...(update.nodeExecutionTimes || {}),
        },
        nodeTokenUsage: {
          ...(current?.nodeTokenUsage || {}),
          ...(update.nodeTokenUsage || {}),
        },
        nodeCallCounts: mergedCallCounts,
      };
    },
    default: () => ({
      startTime: Date.now(),
      nodeExecutionTimes: {},
      nodeTokenUsage: {},
      nodeCallCounts: {},
      totalFilesGenerated: 0,
      totalFilesModified: 0,
      validationRetries: 0,
      totalRounds: 0,
    }),
  }),
});
